1	/**
2	 * Session store — holds session_id for the current extension session.
3	 * Created on extension load via POST /api/sessions.
4	 * Resets on every extension load (never persisted to localStorage).
5	 *
6	 * tokenMap: in-memory token↔real-value mapping for the masking pipeline.
7	 * Keys are opaque tokens (e.g. "CONSULTANT_001"), values are real values.
8	 * Reset alongside sessionId on every extension load (ARC-9).
9	 */
10	class SessionStore {
11	  sessionId = $state<string | null>(null);
12	  tableauUserId = $state<string | null>(null);
13	  tokenMap = $state<Map<string, string>>(new Map());
14	}
15	
16	export const sessionStore = new SessionStore();
